INSERT INTO "customization_websitecustomization" VALUES(1,'Default System Configuration',1,'{"website_name": "MCC Legal & MOU Enterprise Hub", "website_description": "Comprehensive document hub and MOU lifecycle management portal.", "sidebar_title": "MCC LEGAL", "sidebar_subtitle": "Documents"}','{"website_logo": "", "small_logo": "", "white_logo": "", "login_logo": "", "login_bg": "", "favicon": "", "default_avatar": "", "loading_animation": "", "illustration_404": "", "illustration_empty": ""}','{"primary_color": "#4F46E5", "secondary_color": "#0EA5E9", "accent_color": "#F59E0B", "success_color": "#10B981", "warning_color": "#F59E0B", "danger_color": "#EF4444", "info_color": "#3B82F6", "bg_color": "#F8FAFC", "card_color": "#FFFFFF", "sidebar_color": "#0F172A", "navbar_color": "#FFFFFF", "button_style": "rounded", "border_radius": 12, "font_family": "Inter, sans-serif", "font_size": "medium", "icon_pack": "Material UI", "spacing_scale": 1, "shadow_level": "medium", "animation_speed": "normal", "mode": "light"}','[{"id": "nav-1", "label": "Dashboard", "icon": "Dashboard", "route": "/", "order": 1, "roles": ["Super Admin", "Admin", "User"], "visible": true, "new_tab": false}, {"id": "nav-2", "label": "Folder Explorer", "icon": "Folder", "route": "/folders", "order": 2, "roles": ["Super Admin", "Admin", "User"], "visible": true, "new_tab": false}, {"id": "nav-3", "label": "MOUs & Agreements", "icon": "Assignment", "route": "/mous", "order": 3, "roles": ["Super Admin", "Admin", "User"], "visible": true, "new_tab": false}, {"id": "nav-4", "label": "User Management", "icon": "People", "route": "/users", "order": 4, "roles": ["Super Admin", "Admin"], "visible": true, "new_tab": false}, {"id": "nav-5", "label": "Master Data", "icon": "Category", "route": "/master-data", "order": 5, "roles": ["Super Admin", "Admin"], "visible": true, "new_tab": false}, {"id": "nav-6", "label": "Settings & Customizer", "icon": "Settings", "route": "/settings", "order": 6, "roles": ["Super Admin", "Admin", "User"], "visible": true, "new_tab": false}]','{}','{"heading": "Welcome Back to MCC Data Bridge", "subheading": "Sign in to access college MOUs, legal files, and repository archives.", "button_text": "Sign In to Portal", "welcome_message": "Authorized Staff & Administrator Access Only", "left_heading": "MCC LEGAL Documents", "left_subheading": "Professional Memorandum of Understanding Registry", "point_1": "Fully-integrated document version control", "point_2": "Granular user permission matrices", "point_3": "Automated expiry warning system logs", "show_remember_me": true}','{"welcome_text": "Welcome to your MCC Enterprise Workspace", "recent_activity_title": "Recent Organization Activities", "cards_order": ["total_mous", "active_mous", "expiring_soon", "total_files"], "widgets_visibility": {"stats_cards": true, "mou_status_chart": true, "department_distribution": true, "recent_activity_feed": true, "quick_actions": true}}','{"footer_logo": "", "footer_description": "Empowering academic collaboration, institutional MOUs, and legal records compliance.", "social_links": {"facebook": "https://facebook.com", "instagram": "https://instagram.com", "linkedin": "https://linkedin.com", "twitter": "https://twitter.com", "youtube": "https://youtube.com", "github": "https://github.com"}, "quick_links": [{"label": "Official MCC Website", "url": "https://mcc.edu.in"}, {"label": "Privacy Policy", "url": "/privacy"}, {"label": "Terms & Conditions", "url": "/terms"}]}','{"toast_style": "modern", "notification_color": "#4F46E5", "notification_duration": 4000, "success_msg": "Operation completed successfully.", "error_msg": "An unexpected error occurred. Please try again.", "warning_msg": "Please verify your input before proceeding.", "info_msg": "System notification update."}','{"header_title": "MCC Legal & MOU Portal", "footer_text": "Madras Christian College (Autonomous), Tambaram, Chennai.", "button_color": "#4F46E5", "welcome_email": "Welcome to MCC Data Bridge. Your account has been activated.", "password_reset": "Click the button below to reset your password.", "invitation_email": "You have been invited to join the MCC Legal & MOU Hub."}','{"error_401": {"title": "401 - Unauthorized", "subtitle": "Authentication Required", "desc": "Please sign in to view this page.", "button_text": "Go to Login"}, "error_403": {"title": "403 - Forbidden", "subtitle": "Access Denied", "desc": "You do not have permission to view this resource.", "button_text": "Back to Home"}, "error_404": {"title": "404 - Page Not Found", "subtitle": "Lost in Space?", "desc": "The page you are looking for does not exist or has been moved.", "button_text": "Return to Dashboard"}, "error_500": {"title": "500 - Server Error", "subtitle": "Internal Failure", "desc": "Something went wrong on our end. Please try again later.", "button_text": "Reload Page"}, "maintenance": {"title": "Under Scheduled Maintenance", "subtitle": "Upgrading System Capabilities", "desc": "We will be back online shortly. Thank you for your patience.", "button_text": "Check Status"}}','{"en": {"Dashboard": "Dashboard", "Folders": "Folder Explorer", "MOUs": "MOUs & Agreements", "Users": "User Management", "Settings": "Settings & Customizer", "Upload": "Upload Files", "Delete": "Delete", "Edit": "Edit", "Save": "Save Changes", "Cancel": "Cancel"}, "ta": {"Dashboard": "\u0bae\u0bc1\u0b95\u0baa\u0bcd\u0baa\u0bc1 \u0baa\u0bb2\u0b95\u0bc8", "Folders": "\u0b95\u0bcb\u0baa\u0bcd\u0baa\u0bc1 \u0b89\u0bb2\u0bbe\u0bb5\u0bbf", "MOUs": "\u0baa\u0bc1\u0bb0\u0bbf\u0ba8\u0bcd\u0ba4\u0bc1\u0ba3\u0bb0\u0bcd\u0bb5\u0bc1 \u0b92\u0baa\u0bcd\u0baa\u0ba8\u0bcd\u0ba4\u0b99\u0bcd\u0b95\u0bb3\u0bcd", "Users": "\u0baa\u0baf\u0ba9\u0bb0\u0bcd \u0bae\u0bc7\u0bb2\u0bbe\u0ba3\u0bcd\u0bae\u0bc8", "Settings": "\u0b85\u0bae\u0bc8\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bcd", "Upload": "\u0b95\u0bcb\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bc8 \u0baa\u0ba4\u0bbf\u0bb5\u0bc7\u0bb1\u0bcd\u0bb1\u0bc1\u0b95", "Delete": "\u0ba8\u0bc0\u0b95\u0bcd\u0b95\u0bc1\u0b95", "Edit": "\u0ba4\u0bbf\u0bb0\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1\u0b95", "Save": "\u0b9a\u0bc7\u0bae\u0bbf\u0b95\u0bcd\u0b95", "Cancel": "\u0bb0\u0ba4\u0bcd\u0ba4\u0bc1\u0b9a\u0bc6\u0baf\u0bcd"}}','{"custom_css": "/* Global Custom CSS injected by Super Admin */\n.custom-accent-badge { border-radius: 20px; }", "custom_js": "// Global Custom JavaScript injected by Super Admin\nconsole.log(''MCC Customization Script Loaded'');", "custom_html_head": "", "custom_html_body": ""}','2026-08-05 18:34:54.083724','2026-08-06 14:21:38.945374',NULL);
