BEGIN TRANSACTION;
CREATE TABLE "activity_logs_activitylog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" text NOT NULL, "created_at" datetime NOT NULL, "ip_address" char(39) NULL, "user_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "module" varchar(100) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "customization_websitecustomization" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL, "info" text NOT NULL CHECK ((JSON_VALID("info") OR "info" IS NULL)), "branding" text NOT NULL CHECK ((JSON_VALID("branding") OR "branding" IS NULL)), "theme" text NOT NULL CHECK ((JSON_VALID("theme") OR "theme" IS NULL)), "navigation" text NOT NULL CHECK ((JSON_VALID("navigation") OR "navigation" IS NULL)), "pages" text NOT NULL CHECK ((JSON_VALID("pages") OR "pages" IS NULL)), "login" text NOT NULL CHECK ((JSON_VALID("login") OR "login" IS NULL)), "dashboard" text NOT NULL CHECK ((JSON_VALID("dashboard") OR "dashboard" IS NULL)), "footer" text NOT NULL CHECK ((JSON_VALID("footer") OR "footer" IS NULL)), "notification" text NOT NULL CHECK ((JSON_VALID("notification") OR "notification" IS NULL)), "email_templates" text NOT NULL CHECK ((JSON_VALID("email_templates") OR "email_templates" IS NULL)), "error_pages" text NOT NULL CHECK ((JSON_VALID("error_pages") OR "error_pages" IS NULL)), "dynamic_text" text NOT NULL CHECK ((JSON_VALID("dynamic_text") OR "dynamic_text" IS NULL)), "custom_code" text NOT NULL CHECK ((JSON_VALID("custom_code") OR "custom_code" IS NULL)), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "updated_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "files_file" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "size" bigint NOT NULL, "file_type" varchar(100) NOT NULL, "file_field" varchar(100) NULL, "version_number" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "folder_id" bigint NOT NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "file_size" bigint NULL, "google_file_id" varchar(255) NULL, "mime_type" varchar(255) NULL, "web_content_link" varchar(1000) NULL, "web_view_link" varchar(1000) NULL, "is_signed" bool NOT NULL, "encrypted" bool NOT NULL, "encryption_key_id" varchar(100) NOT NULL, "sha256_hash" varchar(64) NULL, "virus_scan_status" varchar(50) NOT NULL, "deleted_at" datetime NULL, "deleted_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "is_deleted" bool NOT NULL);
CREATE TABLE "files_fileversion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "version_number" integer NOT NULL, "name" varchar(255) NOT NULL, "size" bigint NOT NULL, "file_type" varchar(100) NOT NULL, "file_field" varchar(100) NULL, "created_at" datetime NOT NULL, "file_id" bigint NOT NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "google_file_id" varchar(255) NULL, "encrypted" bool NOT NULL, "encryption_key_id" varchar(100) NOT NULL, "sha256_hash" varchar(64) NULL, "virus_scan_status" varchar(50) NOT NULL);
CREATE TABLE "folders_folder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "google_folder_id" varchar(255) NULL, "status" varchar(50) NOT NULL, "expiry_date" date NULL, "summary" text NULL, "deleted_at" datetime NULL, "deleted_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "is_deleted" bool NOT NULL, "custom_page_id" char(32) NULL REFERENCES "users_customdynamicpage" ("id") DEFERRABLE INITIALLY DEFERRED, "module_type" varchar(100) NOT NULL, "parent_id" bigint NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "folders_folderpermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_granted" bool NOT NULL, "folder_id" bigint NOT NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "can_delete_own_uploads" bool NOT NULL, "can_download" bool NOT NULL, "can_read" bool NOT NULL, "can_upload" bool NOT NULL);
CREATE TABLE "folders_folderview" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "viewed_at" datetime NOT NULL, "folder_id" bigint NOT NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "folders_recyclebinsetting" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "retention_period" varchar(50) NOT NULL, "auto_delete_enabled" bool NOT NULL, "updated_at" datetime NOT NULL, "updated_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_collaborationtype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "mous_department" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "is_active" bool NOT NULL, "category_id" bigint NOT NULL REFERENCES "mous_departmentcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_departmentcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "mous_departmentsubmission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "signed_date" date NOT NULL, "mou_month" varchar(20) NOT NULL, "mou_year" integer NOT NULL, "summary" text NOT NULL, "purpose" text NOT NULL, "benefits" text NOT NULL CHECK ((JSON_VALID("benefits") OR "benefits" IS NULL)), "remarks" text NULL, "uploaded_at" datetime NOT NULL, "review_status" varchar(50) NOT NULL, "reviewer_comments" text NULL, "department_id" bigint NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "signed_file_id" bigint NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_documenttype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "mous_mou" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "mou_number" varchar(100) NOT NULL UNIQUE, "partner_organization" varchar(255) NOT NULL, "department_name" varchar(255) NULL, "effective_date" date NULL, "signed_date" date NULL, "expiry_date" date NULL, "duration_months" integer NOT NULL, "status" varchar(50) NOT NULL, "summary" text NULL, "purpose" text NULL, "objectives" text NULL, "beneficiaries" text NULL CHECK ((JSON_VALID("beneficiaries") OR "beneficiaries" IS NULL)), "opportunities" text NULL CHECK ((JSON_VALID("opportunities") OR "opportunities" IS NULL)), "custom_fields_data" text NULL CHECK ((JSON_VALID("custom_fields_data") OR "custom_fields_data" IS NULL)), "coordinator_name" varchar(255) NULL, "coordinator_designation" varchar(255) NULL, "coordinator_email" varchar(254) NULL, "coordinator_phone" varchar(50) NULL, "partner_name" varchar(255) NULL, "partner_designation" varchar(255) NULL, "partner_email" varchar(254) NULL, "partner_phone" varchar(50) NULL, "additional_notes" text NULL, "remarks" text NULL, "version_number" integer NOT NULL, "is_renewed" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "original_mou_id" bigint NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "renewed_from_id" bigint NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "signed_mou_id" bigint NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_type_id" bigint NULL REFERENCES "mous_moutemplate" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_file" varchar(100) NULL);
CREATE TABLE "mous_moucategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "code" varchar(50) NULL, "color" varchar(50) NOT NULL, "icon_type" varchar(50) NOT NULL, "coordinator_name" varchar(255) NULL, "coordinator_email" varchar(254) NULL, "category_type" varchar(50) NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "mous_moudocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "document_type" varchar(50) NOT NULL, "uploaded_at" datetime NOT NULL, "file_id" bigint NOT NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_mourenewal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "renewed_at" datetime NOT NULL, "notes" text NULL, "original_mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "renewed_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "renewed_mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_moushare" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "permission" varchar(50) NOT NULL, "status" varchar(50) NOT NULL, "shared_at" datetime NOT NULL, "department_id" bigint NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "shared_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_moutemplate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "description" text NULL, "template_notes" text NULL, "fields_schema" text NOT NULL CHECK ((JSON_VALID("fields_schema") OR "fields_schema" IS NULL)), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_organizationtype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "mous_tag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "mous_templatecategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "mous_templatecollection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "template_name" varchar(255) NOT NULL, "description" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "mous_templatecategory" ("id") DEFERRABLE INITIALLY DEFERRED, "collaboration_type_id" bigint NOT NULL REFERENCES "mous_collaborationtype" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NOT NULL REFERENCES "mous_department" ("id") DEFERRABLE INITIALLY DEFERRED, "department_category_id" bigint NOT NULL REFERENCES "mous_departmentcategory" ("id") DEFERRABLE INITIALLY DEFERRED, "organization_type_id" bigint NOT NULL REFERENCES "mous_organizationtype" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_templatecollection_tags" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "templatecollection_id" bigint NOT NULL REFERENCES "mous_templatecollection" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "mous_tag" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_templatedocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "document_name" varchar(255) NOT NULL, "version" varchar(50) NOT NULL, "effective_date" date NULL, "expiry_date" date NULL, "revision_date" date NULL, "remarks" text NULL, "uploaded_at" datetime NOT NULL, "status" varchar(50) NOT NULL, "document_type_id" bigint NOT NULL REFERENCES "mous_documenttype" ("id") DEFERRABLE INITIALLY DEFERRED, "template_collection_id" bigint NOT NULL REFERENCES "mous_templatecollection" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "google_file_id" varchar(255) NULL, "file_path" varchar(100) NULL);
CREATE TABLE "notifications_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "description" text NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "metadata" text NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)));
CREATE TABLE "permissions_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "codename" varchar(100) NOT NULL UNIQUE, "description" text NULL);
CREATE TABLE "roles_role" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "description" text NULL);
CREATE TABLE "roles_rolepermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "permission_id" bigint NOT NULL REFERENCES "permissions_permission" ("id") DEFERRABLE INITIALLY DEFERRED, "role_id" bigint NOT NULL REFERENCES "roles_role" ("id") DEFERRABLE INITIALLY DEFERRED);
