CREATE TABLE "users_customuser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "phone" varchar(20) NULL, "designation" varchar(100) NULL, "department" varchar(100) NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "role_id" bigint NULL REFERENCES "roles_role" ("id") DEFERRABLE INITIALLY DEFERRED, "stream" varchar(100) NULL, "company_name" varchar(200) NULL, "password_changed_at" datetime NOT NULL);
