CREATE TABLE "users_userinvitation" ("id" char(32) NOT NULL PRIMARY KEY, "email" varchar(254) NOT NULL, "stream" varchar(100) NOT NULL, "department" varchar(100) NOT NULL, "token" varchar(255) NOT NULL UNIQUE, "expires_at" datetime NOT NULL, "is_used" bool NOT NULL, "is_cancelled" bool NOT NULL, "created_at" datetime NOT NULL, "accepted_at" datetime NULL, "ip_address" char(39) NULL, "user_agent" text NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "system_role_id" bigint NOT NULL REFERENCES "roles_role" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_userpermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_granted" bool NOT NULL, "permission_id" bigint NOT NULL REFERENCES "permissions_permission" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
